package com.pocketmusic.android;
import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.*;import java.io.*;import java.nio.file.Files;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
public class FeedRecoveryTest {
 private Context c;private File root;private String prefs;private AccountMusic.Transport old;
 @Before public void setup()throws Exception{Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();root=Files.createTempDirectory(app.getCacheDir().toPath(),"feed-recovery-").toFile();prefs="feed-recovery-"+UUID.randomUUID();c=new ContextWrapper(app){public File getNoBackupFilesDir(){return root;}public File getCacheDir(){return root;}public SharedPreferences getSharedPreferences(String k,int m){return super.getSharedPreferences(prefs,m);}};old=AccountMusic.transport;YouTubeSession.save(c,SessionAuth.capture("SAPISID=synthetic; __Secure-3PSID=synthetic","fixture-visitor","fixture-channel","2","1.fixture").identity("Fixture listener"));}
 @After public void cleanup(){AccountMusic.transport=old;c.deleteSharedPreferences(prefs);for(File f:root.listFiles())f.delete();root.delete();}
 private JSONObject card()throws Exception{return new JSONObject("{musicTwoRowItemRenderer:{title:{runs:[{text:'Fixture song'}]},navigationEndpoint:{watchEndpoint:{videoId:'abcdefghijk',watchEndpointMusicSupportedConfigs:{watchEndpointMusicConfig:{musicVideoType:'MUSIC_VIDEO_TYPE_ATV'}}}}}}");}
 private JSONObject home(JSONArray contents)throws Exception{return new JSONObject().put("responseContext",new JSONObject("{mainAppWebResponseContext:{loggedOut:false}}")).put("contents",new JSONArray().put(new JSONObject().put("musicCarouselShelfRenderer",new JSONObject().put("contents",contents))));}
 @Test public void brokenOptionalMixCannotDiscardDirectAccountSongs()throws Exception{JSONObject data=home(new JSONArray().put(card()).put(new JSONObject("{musicTwoRowItemRenderer:{navigationEndpoint:{browseEndpoint:{browseId:'VLFIXTURE'}}}}")));AccountMusic.transport=(p,path,cookie,auth,body,user,visitor,version)->{if(new JSONObject(body).optString("browseId").equals("FEmusic_home"))return data.toString();throw new IOException("Unavailable optional mix");};assertEquals("abcdefghijk",AccountMusic.load(c,"test-partial").get(0).tracks.get(0).id);}
 @Test public void radioCardsUseTheMusicNextEndpointAndParseItsPanel()throws Exception{JSONObject data=home(new JSONArray().put(new JSONObject("{musicTwoRowItemRenderer:{navigationEndpoint:{watchPlaylistEndpoint:{playlistId:'RDFIXTURE'}}}}")));JSONObject panel=new JSONObject().put("responseContext",new JSONObject("{mainAppWebResponseContext:{loggedOut:false}}")).put("playlistPanelRenderer",new JSONObject().put("contents",new JSONArray().put(new JSONObject().put("playlistPanelVideoWrapperRenderer",new JSONObject().put("primaryRenderer",new JSONObject().put("playlistPanelVideoRenderer",card().getJSONObject("musicTwoRowItemRenderer"))).put("counterpart",new JSONArray().put(card()))))));AccountMusic.transport=(p,path,cookie,auth,body,user,visitor,version)->{if(path.contains("/next")){assertEquals("RDFIXTURE",new JSONObject(body).getString("playlistId"));assertTrue(new JSONObject(body).getBoolean("isAudioOnly"));assertTrue(new JSONObject(body).getBoolean("enablePersistentPlaylistPanel"));return panel.toString();}return data.toString();};assertEquals("abcdefghijk",AccountMusic.load(c,"test-radio").get(0).tracks.get(0).id);}
 @Test public void missingLoggedOutFieldRequiresIdentityVerificationInsteadOfFalseExpiry()throws Exception{JSONObject data=home(new JSONArray().put(card()));data.remove("responseContext");AtomicInteger checks=new AtomicInteger();AccountMusic.transport=(p,path,cookie,auth,body,user,visitor,version)->{if(path.contains("account_menu")){checks.incrementAndGet();return "{activeAccountHeaderRenderer:{accountName:{simpleText:'Fixture listener'}}}";}return data.toString();};assertFalse(AccountMusic.load(c,"test-context").isEmpty());assertEquals(1,checks.get());}
 @Test public void explicitlySignedOutHomeNeverBecomesAccountPicks()throws Exception{AccountMusic.transport=(p,path,cookie,auth,body,user,visitor,version)->"{responseContext:{mainAppWebResponseContext:{loggedOut:true}}}";try{AccountMusic.load(c,"test-expired");fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("expired"));}}
 @Test public void overlayTypeAndMusicArtistCreditRecoverSongsWithoutAdmittingGeneralVideos()throws Exception{JSONObject song=card().getJSONObject("musicTwoRowItemRenderer"),watch=song.getJSONObject("navigationEndpoint").getJSONObject("watchEndpoint");JSONObject config=watch.getJSONObject("watchEndpointMusicSupportedConfigs");watch.remove("watchEndpointMusicSupportedConfigs");song.put("overlay",new JSONObject().put("watchEndpoint",new JSONObject().put("videoId","abcdefghijk").put("watchEndpointMusicSupportedConfigs",config)));assertEquals(1,AccountMusic.parse(home(new JSONArray().put(new JSONObject().put("musicTwoRowItemRenderer",song)))).size());song.remove("overlay");assertTrue(AccountMusic.parse(home(new JSONArray().put(new JSONObject().put("musicTwoRowItemRenderer",song)))).isEmpty());song.put("subtitle",new JSONObject("{runs:[{text:'Fixture artist',navigationEndpoint:{browseEndpoint:{browseId:'UCFIXTURE',browseEndpointContextSupportedConfigs:{browseEndpointContextMusicConfig:{pageType:'MUSIC_PAGE_TYPE_ARTIST'}}}}}]}"));assertEquals(1,AccountMusic.parse(home(new JSONArray().put(new JSONObject().put("musicTwoRowItemRenderer",song)))).size());}
 @Test public void emptyHomeFallsBackToAccountLikesWithAnHonestLabel()throws Exception{AccountMusic.transport=(p,path,cookie,auth,body,user,visitor,version)->{String id=new JSONObject(body).optString("browseId");return home(id.equals("VLLM")?new JSONArray().put(card()):new JSONArray()).toString();};assertEquals("Your YouTube Music likes",AccountMusic.load(c,"test-likes").get(0).title);}
 @Test public void verifiedAvatarIsEncryptedAndOldSessionPayloadsStayCompatible()throws Exception{AccountMusic.transport=(p,path,cookie,auth,body,user,visitor,version)->"{activeAccountHeaderRenderer:{accountName:{simpleText:'Fixture listener'},accountPhoto:{thumbnails:[{url:'https://evil.com/image'},{url:'https://lh3.googleusercontent.com/a/fixture'}]}}}";SessionAuth avatar=AccountMusic.verifyAccount(YouTubeSession.read(c),"test-photo");assertEquals("https://lh3.googleusercontent.com/a/fixture",avatar.avatarUrl);YouTubeSession.save(c,avatar);assertEquals(avatar.avatarUrl,YouTubeSession.read(c).avatarUrl);JSONObject legacy=new JSONObject(avatar.encode());legacy.remove("avatarUrl");assertEquals("",SessionAuth.decode(legacy.toString()).avatarUrl);}
 @Test public void delayedProfileResponseCannotOverwriteANewerAccount()throws Exception{SessionAuth first=YouTubeSession.read(c);String before=YouTubeSession.fingerprint(c);SessionAuth second=SessionAuth.capture("SAPISID=synthetic-second; __Secure-3PSID=synthetic-second","second-visitor","second-channel","1","1.fixture").identity("Second listener");YouTubeSession.save(c,second);String next=YouTubeSession.fingerprint(c);assertNull(YouTubeSession.updateProfile(c,before,first.avatar("https://lh3.googleusercontent.com/a/old")));assertEquals(next,YouTubeSession.fingerprint(c));assertEquals("Second listener",YouTubeSession.read(c).accountName);assertNotNull(YouTubeSession.updateProfile(c,next,second.avatar("https://lh3.googleusercontent.com/a/current")));assertEquals("Second listener",YouTubeSession.read(c).accountName);assertEquals("Changing a photo must not invalidate playback/feed scopes",next,YouTubeSession.fingerprint(c));}
 @Test public void smartDownloadsFetchConnectedAccountWithoutLocalHistory()throws Exception{AccountMusic.Source source=Recommendations.accountSource;SmartDownloads.Fetcher fetch=SmartDownloads.fetcher;java.util.function.Predicate<Context> eligible=SmartDownloads.eligible;File downloaded=null;try{Track song=new Track("smrtacct001","Account offline fixture","Fixture artist",180,true,"");c.getSharedPreferences("music",0).edit().putBoolean("smartEnabled",true).putBoolean("smartConsent",true).commit();assertTrue(MusicTaste.recent(c).isEmpty());Recommendations.accountSource=(context,process)->List.of(new DiscoveryShelf("For you","Account",List.of(song)));SmartDownloads.eligible=context->true;SmartDownloads.fetcher=(context,track,stage,run)->{File audio=new File(stage,track.id+".m4a");try(FileOutputStream out=new FileOutputStream(audio)){out.write(new byte[512]);}return audio;};SmartDownloads.refresh(c,new SmartDownloads.Run());downloaded=MusicRepository.local(c,song.id);assertNotNull(SmartDownloads.status(c),downloaded);assertTrue(SmartDownloads.owned(c,downloaded));assertTrue(SmartDownloads.status(c),SmartDownloads.status(c).contains("1 added"));assertEquals("account",c.getSharedPreferences("music",0).getString("musicOrigin",""));}finally{if(downloaded!=null)downloaded.delete();Recommendations.accountSource=source;SmartDownloads.fetcher=fetch;SmartDownloads.eligible=eligible;}}
}
